<template><aside v-if="missing.length" class="opening-notice" role="status"><strong>Your profile is Open without published {{missing.map(m=>m.format==='IN_PERSON'?'in-person':'virtual').join(' and ')}} openings.</strong><p>Providers with published availability receive priority on the website. Add recurring openings or choose Waitlist or Closed.</p><button type="button" @click="$emit('open')">Set availability</button></aside></template>
<script setup>
import {ref,watch,onMounted,onUnmounted} from 'vue';import api from '../../services/api';const props=defineProps({providerId:[Number,String],agencyId:[Number,String]});defineEmits(['open']);const missing=ref([]);let generation=0;
async function load(){const g=++generation;if(!props.providerId||!props.agencyId){missing.value=[];return;}try{const {data}=await api.get(`/availability/providers/${props.providerId}/public-settings`,{params:{agencyId:props.agencyId},skipGlobalLoading:true});if(g===generation)missing.value=data.reminders||[];}catch{if(g===generation)missing.value=[];}}
watch(()=>[props.providerId,props.agencyId],load,{immediate:true});onMounted(()=>window.addEventListener('focus',load));onUnmounted(()=>{generation++;window.removeEventListener('focus',load);});
</script><style scoped>.opening-notice{padding:18px;border:1px solid #c89934;background:#fff7df;color:#563c12;border-radius:12px;margin-bottom:18px}.opening-notice p{margin:8px 0}.opening-notice button{padding:9px 14px;background:#553f18;color:white;border:0;border-radius:6px}</style>
